codeExamples.code:
-- Replication factor N = 3
CREATE KEYSPACE app
  WITH replication = {'class': 'NetworkTopologyStrategy', 'dc1': 3};

-- Eventual consistency: fast, may read stale (R=1)
CONSISTENCY ONE;
SELECT balance FROM app.accounts WHERE id = 'a1';

-- Strong consistency for this key: QUORUM write (W=2) + QUORUM read (R=2)
-- R + W = 2 + 2 = 4 > N = 3  ==> read quorum overlaps write quorum
CONSISTENCY QUORUM;
UPDATE app.accounts SET balance = 500 WHERE id = 'a1';
SELECT balance FROM app.accounts WHERE id = 'a1';

-- Read-modify-write atomicity needs a lightweight transaction (Paxos), not just QUORUM
UPDATE app.accounts SET balance = 400
  WHERE id = 'a1' IF balance = 500;   -- compare-and-set via Paxos
